import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiStructure","description":"","frontmatter":{},"headers":[],"relativePath":"modules/structure/index.md","filePath":"modules/structure/index.md","lastUpdated":0}`),a={name:`modules/structure/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakistructure" tabindex="-1">EmakiStructure <a class="header-anchor" href="#emakistructure" aria-label="Permalink to “EmakiStructure”">​</a></h1><p>EmakiStructure 是结构生成与多方块结构交互模块. 它允许服主框选区域导出 <code>.nbt</code> 结构模板并按朝向放置, 记录并触发多方块结构定义, 在生成中断时事务回滚, 拦截替换尚未生成区块中的原版结构, 还支持从 ItemsAdder / Oraxen / Nexo / CraftEngine 四源识别与还原家具</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to “基本信息”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>1.0.4</code></td></tr><tr><td>构建产物</td><td><code>EmakiStructure-1.0.4.jar</code></td></tr><tr><td>API 坐标</td><td><code>emaki.jiuwu.craft:emaki-structure-api:1.0.1</code> (仅 <code>compileOnly</code>, 不放入 <code>plugins/</code>)</td></tr><tr><td>主命令</td><td><code>/emakistructure</code> (别名 <code>/ems</code>, <code>/estruct</code>)</td></tr><tr><td>硬依赖</td><td>EmakiCoreLib (<code>required: true</code>)</td></tr><tr><td>软依赖</td><td>MythicMobs, EmakiMobs, ItemsAdder, Oraxen, Nexo, CraftEngine (均为 <code>required: false</code>, 缺失时对应能力降级)</td></tr><tr><td>权限节点</td><td><code>emakistructure.use</code>, <code>emakistructure.edit</code>, <code>emakistructure.reload</code>, <code>emakistructure.admin</code></td></tr><tr><td>描述符基线</td><td><code>api-version: &quot;1.21.8&quot;</code>, <code>folia-supported: true</code></td></tr></tbody></table><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>EmakiStructure 是 <code>.key</code> 门控的私有模块: 仓库根存在 <code>.key</code> 文件时才参与默认构建</p></div><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to “功能页面”">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td>框选, 导出, 放置, 多方块与调试命令</td></tr><tr><td><a href="./templates.html">结构模板</a></td><td>选区高亮, <code>.nbt</code> 导入导出校验, 生物点位与家具侧车</td></tr><tr><td><a href="./multiblocks.html">多方块结构</a></td><td><code>multiblocks/*.yml</code> 定义, 触发与增量检测</td></tr><tr><td><a href="./configuration.html">配置详解</a></td><td><code>config.yml</code> 全部配置键说明</td></tr><tr><td><a href="./api.html">API 与集成</a></td><td><code>emaki-structure-api</code> 门面与 <code>MultiblockTriggerEvent</code></td></tr></tbody></table><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to “核心能力”">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>两点框选</td><td><code>/ems select pos1/pos2</code> 设点, <code>adjust</code> 微调, <code>clear</code> 清除; 选区以发光 <code>BlockDisplay</code> 连续线框高亮 (受视距与世界边界约束)</td></tr><tr><td>结构模板</td><td>选区导出为 <code>structures/&lt;名称&gt;.nbt</code>, 按朝向 (含镜像) 放置; 导入时逐项校验体积, 调色板与方块实体载荷</td></tr><tr><td>生成护栏</td><td>每 tick 写入限额, TPS 自适应限流, 队列超时, 支撑面策略 (<code>skip</code>/<code>keep</code>/<code>fill</code>), 玩家被困检测</td></tr><tr><td>事务回滚</td><td>生成中断 (reload / 停服 / 超时 / 超限) 时按 delta 快照回滚到生成前状态, 启动期自动清理未提交事务</td></tr><tr><td>原版结构拦截替换</td><td>对尚未生成的区块按 <code>replace_rules</code> 用自备模板替换原版结构 (如村庄), 已生成区块永不改写</td></tr><tr><td>多方块结构</td><td>按选区导出 <code>multiblocks/&lt;id&gt;.yml</code>, 玩家交互满足形状时触发配置动作; 支持形状校验, 冷却, 条件与增量检测</td></tr><tr><td>家具四源</td><td>导出时识别 ItemsAdder / Oraxen / Nexo / CraftEngine 家具写入 <code>furniture/&lt;模板&gt;.yml</code> 侧车, 放置时按朝向还原, 回滚时移除</td></tr><tr><td>结构内生物</td><td><code>spawns/&lt;模板&gt;.yml</code> 侧车在结构生成时按点位/球体/区域生成生物 (含 <code>minecraft:</code>/<code>mythicmobs:</code>/<code>emakimobs:</code> 前缀)</td></tr></tbody></table><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to “默认配置目录”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiStructure/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── structures/           ← .nbt 结构模板 (structure export 产物)</span></span>
<span class="line"><span>├── multiblocks/          ← 多方块定义 (multiblock export 产物)</span></span>
<span class="line"><span>├── spawns/               ← 结构内生物点位侧车</span></span>
<span class="line"><span>├── furniture/            ← 家具还原侧车 (导出结构时生成)</span></span>
<span class="line"><span>├── journal/              ← 生成事务回滚日志 (运行期文件)</span></span>
<span class="line"><span>├── replaced/             ← 原版结构替换 marker (运行期文件)</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><p><code>structures/</code> 与 <code>multiblocks/</code> 由游戏内命令导出生成, 也可手工放入; <code>spawns/</code>, <code>furniture/</code> 手工编写; <code>journal/</code> 与 <code>replaced/</code> 是运行期文件, 不要手工编辑. 文件保存后执行 <code>/ems reload</code> 生效</p><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to “典型工作流”">​</a></h2><ol><li><code>/ems select pos1</code> / <code>pos2</code> 框选区域, 确认选区尺寸</li><li><code>/ems structure export &lt;名称&gt;</code> 导出为 <code>structures/&lt;名称&gt;.nbt</code></li><li>(可选) 为该模板编写 <code>spawns/&lt;名称&gt;.yml</code> 生成生物点位; 结构含家具插件方块时家具侧车随导出生成</li><li><code>/ems get &lt;名称&gt; [朝向]</code> 就地预览, 或 <code>/ems structure place &lt;名称&gt; &lt;朝向&gt;</code> 正式放置</li><li>多方块: <code>/ems multiblock export &lt;id&gt;</code> 按选区记录布局, 玩家凑齐形状后自动触发动作</li><li>出现原版结构替换需求时在 <code>config.yml</code> 的 <code>replace_rules</code> 中声明规则</li></ol><h2 id="与其他模块的关系" tabindex="-1">与其他模块的关系 <a class="header-anchor" href="#与其他模块的关系" aria-label="Permalink to “与其他模块的关系”">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>协作方式</th></tr></thead><tbody><tr><td>EmakiCoreLib</td><td>硬依赖: 调度器, 调试命令, 消息与配置预检基础设施; 多方块触发动作走 CoreLib 动作管道</td></tr><tr><td>EmakiMobs / MythicMobs</td><td><code>spawns/</code> 侧车可生成 <code>emakimobs:</code> / <code>mythicmobs:</code> 前缀的自定义生物 (均为可选依赖)</td></tr><tr><td>ItemsAdder / Oraxen / Nexo / CraftEngine</td><td>家具与自定义方块的可选来源, 缺失时对应家具条目跳过并告警</td></tr></tbody></table>`,16)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};